"""Evaluate an ACT checkpoint with the existing robomimic Can image runner."""
from __future__ import annotations
import argparse, copy, functools, json, sys
from pathlib import Path
import numpy as np
import torch

CAMERAS = ['agentview_image', 'robot0_eye_in_hand_image']

class ACTCanPolicy:
    def __init__(self, checkpoint, act_root, device):
        sys.path.insert(0, str(act_root))
        from policy import ACTPolicy
        from diffusion_policy.model.common.module_attr_mixin import ModuleAttrMixin
        # These checkpoints are generated by the local training runner and
        # contain NumPy normalization arrays in addition to the state dict.
        payload = torch.load(checkpoint, map_location=device, weights_only=False)
        self.q_mean = torch.as_tensor(payload['q_mean'], device=device).float()
        self.q_std = torch.as_tensor(payload['q_std'], device=device).float()
        self.a_mean = torch.as_tensor(payload['a_mean'], device=device).float()
        self.a_std = torch.as_tensor(payload['a_std'], device=device).float()
        self.policy = ACTPolicy(payload['config']); self.policy.load_state_dict(payload['model'])
        self.policy.to(device); self.policy.eval(); self.device = torch.device(device); self.dtype = torch.float32

    def reset(self):
        pass

    def predict_action(self, obs_dict):
        q = torch.cat([obs_dict[k][:, -1].float() for k in ['robot0_eef_pos','robot0_eef_quat','robot0_gripper_qpos']], dim=-1)
        q = (q - self.q_mean) / self.q_std
        q14 = torch.zeros((q.shape[0], 14), device=q.device, dtype=q.dtype); q14[:, :9] = q
        ims = [obs_dict[k][:, -1].float() for k in CAMERAS]
        image = torch.stack(ims, dim=1)
        with torch.no_grad():
            pred = self.policy(q14, image)
        action = pred[..., :10] * self.a_std[:10] + self.a_mean[:10]
        return {'action': action}

def main():
    p=argparse.ArgumentParser()
    p.add_argument('--checkpoint', required=True)
    p.add_argument('--out', required=True)
    p.add_argument('--act-root', required=True)
    p.add_argument('--project-root', required=True,
                   help='Local checkout containing the robomimic image runner')
    p.add_argument('--asset', required=True, help='Can image HDF5 used for evaluation')
    p.add_argument('--device', default='cuda')
    p.add_argument('--n-test', type=int, default=100)
    args=p.parse_args()
    if args.device.startswith('cuda') and not torch.cuda.is_available():
        raise RuntimeError('CUDA was requested but is not available')
    project = Path(args.project_root).expanduser().resolve()
    act_root = Path(args.act_root).expanduser().resolve()
    sys.path.insert(0, str(project))
    import diffusion_policy.env_runner.robomimic_image_runner as runner_module
    from robomimic.utils import env_utils as EnvUtils
    from robomimic.utils import obs_utils as ObsUtils
    try:
        from robosuite.controllers.composite.composite_controller_factory import (
            refactor_composite_controller_config,
        )
    except ImportError:
        # RoboSuite 1.4.1 is the version recorded in the Can-MH dataset and
        # uses the archived OSC_POSE controller directly.
        refactor_composite_controller_config = None

    # Can-MH was recorded with RoboSuite <=1.4.1. Convert its legacy
    # controller metadata before the current RoboSuite constructs the env.
    def create_legacy_compatible_env(env_meta, shape_meta, enable_render=True):
        meta = copy.deepcopy(env_meta)
        kwargs = meta.setdefault('env_kwargs', {})
        controller = kwargs.get('controller_configs')
        if refactor_composite_controller_config is not None and isinstance(controller, dict) and str(controller.get('type', '')).upper() in {
            'OSC_POSE', 'JOINT_POSITION', 'IK_POSE', 'JOINT_VELOCITY',
        }:
            robots = kwargs.get('robots', ['Panda'])
            robot = robots[0] if isinstance(robots, (list, tuple)) else robots
            kwargs['controller_configs'] = refactor_composite_controller_config(
                controller_config=controller, robot_type=robot, arms=['right'])
            kwargs['lite_physics'] = False
        elif isinstance(controller, dict):
            # Keep the dataset's native 1.4.1 controller and only switch its
            # target convention to absolute actions for this evaluator.
            controller['control_delta'] = False
        # The archived env metadata omits camera_names even though the frozen
        # ACT/cache contract uses both Can RGB views.
        kwargs['camera_names'] = ['agentview', 'robot0_eye_in_hand']
        kwargs['camera_heights'] = 84
        kwargs['camera_widths'] = 84
        modality_mapping = __import__('collections').defaultdict(list)
        for key, attr in shape_meta['obs'].items():
            modality_mapping[attr.get('type', 'low_dim')].append(key)
        ObsUtils.initialize_obs_modality_mapping_from_dict(modality_mapping)
        return EnvUtils.create_env_from_metadata(
            env_meta=meta, render=False, render_offscreen=enable_render,
            use_image_obs=enable_render)

    runner_module.create_env = create_legacy_compatible_env
    # RoboSuite exposes a custom OrderedDict observation space. The bundled
    # async runner supports it, but only with shared memory disabled.
    from diffusion_policy.gym_util.async_vector_env import AsyncVectorEnv as _AsyncVectorEnv
    runner_module.AsyncVectorEnv = functools.partial(_AsyncVectorEnv, shared_memory=False)
    RobomimicImageRunner = runner_module.RobomimicImageRunner
    shape_meta = {'obs': {
        'agentview_image': {'shape':[3,84,84], 'type':'rgb'},
        'robot0_eye_in_hand_image': {'shape':[3,84,84], 'type':'rgb'},
        'robot0_eef_pos': {'shape':[3]}, 'robot0_eef_quat': {'shape':[4]},
        'robot0_gripper_qpos': {'shape':[2]}}, 'action': {'shape':[10]}}
    runner = RobomimicImageRunner(output_dir=str(Path(args.out).parent), dataset_path=str(Path(args.asset).expanduser().resolve()), shape_meta=shape_meta,
        n_train=0, n_train_vis=0, n_test=args.n_test, n_test_vis=0, test_start_seed=530000,
        max_steps=500, n_obs_steps=1, n_action_steps=100, render_obs_key='agentview_image',
        abs_action=True, n_envs=8, tqdm_interval_sec=10.0)
    policy = ACTCanPolicy(args.checkpoint, act_root, args.device)
    result = runner.run(policy)
    Path(args.out).write_text(json.dumps({k: float(v) if np.isscalar(v) else v for k,v in result.items()}, indent=2))
    print(json.dumps(result, indent=2))

if __name__ == '__main__': main()
